function longestPath(parent, s) {
  const n = parent.length;
  const children = Array.from({ length: n }, () => []);
  for (let node = 1; node < n; node++) {
    children[parent[node]].push(node);
  }
  let best = 0;

  function chainFrom(node) {
    let first = 0;
    let second = 0;
    for (const child of children[node]) {
      const chain = chainFrom(child);
      if (s[child] === s[node]) {
        continue;
      }
      if (chain > first) {
        second = first;
        first = chain;
      } else if (chain > second) {
        second = chain;
      }
    }
    best = Math.max(best, first + second + 1);
    return first + 1;
  }

  chainFrom(0);
  return best;
}

