function longestPath(parent, s) {
  // Keep only edges whose ends differ, then measure the farthest node reachable from every start.
  const n = parent.length;
  const adj = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    if (s[i] !== s[parent[i]]) {
      adj[i].push(parent[i]);
      adj[parent[i]].push(i);
    }
  }
  let best = 1;
  for (let start = 0; start < n; start++) {
    const dist = new Array(n).fill(-1);
    dist[start] = 1;
    const queue = [start];
    for (let q = 0; q < queue.length; q++) {
      const u = queue[q];
      if (dist[u] > best) best = dist[u];
      for (const v of adj[u]) {
        if (dist[v] === -1) {
          dist[v] = dist[u] + 1;
          queue.push(v);
        }
      }
    }
  }
  return best;
}

