function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  const shape = Math.floor(rand() * 4);
  // Build a tree where every node's parent comes earlier, then shuffle the labels 1..n-1.
  const oldParent = [-1];
  for (let i = 1; i < n; i++) {
    if (shape === 1) oldParent.push(i - 1);
    else if (shape === 2) oldParent.push(rand() < 0.8 ? 0 : Math.floor(rand() * i));
    else if (shape === 3) oldParent.push(Math.max(0, i - 1 - Math.floor(rand() * 3)));
    else oldParent.push(Math.floor(rand() * i));
  }
  const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = rest.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rest[i], rest[j]] = [rest[j], rest[i]];
  }
  const label = [0, ...rest];
  const parent = new Array(n);
  parent[0] = -1;
  for (let i = 1; i < n; i++) parent[label[i]] = label[oldParent[i]];
  const letters = large ? [2, 3, 26][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 3);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [parent, s];
}
